package org.humanjourney.core.geography;
import java.util.*;
import com.google.gson.*;
import org.humanjourney.core.mapfeature.FeatureGeometry;
import org.humanjourney.core.water.WaterGeography.Point;
/** Geography budgets over the same immutable topology/containment primitives as water Map Features. */
public final class GeographyGeometry {
 public static final int MAX_VERTICES=16384,MAX_RINGS=512,CATALOG_VERTICES=1179648,CATALOG_RINGS=65536;
 public static String counts(long vertices,long rings){return "vertices="+vertices+" limit="+MAX_VERTICES+", rings="+rings+" limit="+MAX_RINGS;}
 public static FeatureGeometry check(FeatureGeometry g){if(g.kind()==FeatureGeometry.Kind.POLYLINE||g.vertexCount()>MAX_VERTICES||g.ringCount()>MAX_RINGS)throw new IllegalArgumentException("invalid areal geography capacity: "+counts(g.vertexCount(),g.ringCount()));return g;}
 public static void catalog(Collection<FeatureGeometry> shapes){long vertices=0,rings=0;for(var g:shapes){check(g);vertices+=g.vertexCount();rings+=g.ringCount();if(vertices>CATALOG_VERTICES||rings>CATALOG_RINGS)throw new IllegalArgumentException("aggregate geography geometry budget exceeded: vertices="+vertices+" limit="+CATALOG_VERTICES+" rings="+rings+" limit="+CATALOG_RINGS);}}
 private static void keys(JsonObject o,String... allowed){var set=Set.of(allowed);for(String k:o.keySet())if(!set.contains(k))throw new IllegalArgumentException("unknown geography geometry field: "+k);}
 public static List<Point> points(JsonElement e,int min,int max){if(e==null||!e.isJsonArray()||e.getAsJsonArray().size()<min||e.getAsJsonArray().size()>max)throw new IllegalArgumentException("invalid geography point count");var out=new ArrayList<Point>();for(var v:e.getAsJsonArray()){if(!v.isJsonArray()||v.getAsJsonArray().size()!=2)throw new IllegalArgumentException("point must be[X,Z]");var a=v.getAsJsonArray();for(var n:a)if(!n.isJsonPrimitive()||!n.getAsJsonPrimitive().isNumber())throw new IllegalArgumentException("point must be numeric");out.add(new Point(a.get(0).getAsDouble(),a.get(1).getAsDouble()));}return out;}
 private static final class Budget{int rings,vertices;FeatureGeometry.Ring ring(JsonElement e,String context){try{var p=points(e,3,MAX_VERTICES);vertices+=p.size();if(++rings>MAX_RINGS||vertices>MAX_VERTICES)throw new IllegalArgumentException(counts(vertices,rings));return new FeatureGeometry.Ring(p);}catch(RuntimeException error){throw new IllegalArgumentException(context+": "+error.getMessage(),error);}}}
 private static FeatureGeometry.Part part(JsonElement input,Budget budget,String context){try{if(input==null||!input.isJsonObject())throw new IllegalArgumentException("part must be object");var o=input.getAsJsonObject();keys(o,"outer","holes");var outer=budget.ring(o.get("outer"),context+" outer");var holes=new ArrayList<FeatureGeometry.Ring>();if(o.has("holes")){if(!o.get("holes").isJsonArray()||o.getAsJsonArray("holes").size()>MAX_RINGS-1)throw new IllegalArgumentException("invalid hole count");int i=0;for(var h:o.getAsJsonArray("holes"))holes.add(budget.ring(h,context+" hole["+i+++"]"));}return new FeatureGeometry.Part(outer,holes);}catch(RuntimeException error){throw new IllegalArgumentException(context+": "+error.getMessage(),error);}}
 private static long[] countPart(JsonElement input){if(input==null||!input.isJsonObject())return new long[]{0,0};var o=input.getAsJsonObject();long vertices=0,rings=0;if(o.has("outer")&&o.get("outer").isJsonArray()){vertices+=o.getAsJsonArray("outer").size();rings++;}if(o.has("holes")&&o.get("holes").isJsonArray())for(var h:o.getAsJsonArray("holes")){if(h.isJsonArray())vertices+=h.getAsJsonArray().size();rings++;}return new long[]{vertices,rings};}
 private static void capacity(JsonObject o,String context){long vertices=0,rings=0;if(o.has("polygons")&&o.get("polygons").isJsonArray()){for(var p:o.getAsJsonArray("polygons")){var n=countPart(p);vertices+=n[0];rings+=n[1];}}else{var n=countPart(o);vertices=n[0];rings=n[1];}if(vertices>MAX_VERTICES||rings>MAX_RINGS)throw new IllegalArgumentException(context+": "+counts(vertices,rings));}
 public static FeatureGeometry parse(JsonElement input,String context){if(input==null||!input.isJsonObject())throw new IllegalArgumentException(context+": geometry must be object");var o=input.getAsJsonObject();if(!o.has("type")||!o.get("type").isJsonPrimitive()||!o.getAsJsonPrimitive("type").isString())throw new IllegalArgumentException(context+": geometry type required");capacity(o,context);var budget=new Budget();return switch(o.get("type").getAsString()){
  case "polygon"->{keys(o,"type","outer","holes");var body=o.deepCopy();body.remove("type");yield check(FeatureGeometry.polygon(part(body,budget,context+" polygon")));}
  case "multipolygon"->{keys(o,"type","polygons");if(!o.has("polygons")||!o.get("polygons").isJsonArray()||o.getAsJsonArray("polygons").isEmpty()||o.getAsJsonArray("polygons").size()>MAX_RINGS)throw new IllegalArgumentException(context+": invalid polygon part count");var parts=new ArrayList<FeatureGeometry.Part>();int i=0;for(var p:o.getAsJsonArray("polygons"))parts.add(part(p,budget,context+" component["+i+++"]"));yield check(FeatureGeometry.multipolygon(parts));}
  default->throw new IllegalArgumentException(context+": geography supports polygon/multipolygon only");};}
 private GeographyGeometry(){}
}
